package com.nexusdrive.metadata.service.impl;import com.nexusdrive.common.util.ConsistentHashingUtil;import com.nexusdrive.metadata.service.ChunkOrchestrationService;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;@Service public class ChunkOrchestrationServiceImpl implements ChunkOrchestrationService{private final Map<String,String> urls=new LinkedHashMap<>();private final ConsistentHashingUtil ring;private final RestClient http=RestClient.create();private final String secret;private final int factor;public ChunkOrchestrationServiceImpl(@Value("${storage.nodes}")String value,@Value("${storage.internal-secret}")String secret,@Value("${storage.replication-factor:3}")int factor){for(String raw:value.split(",")){String u=raw.trim();if(!u.startsWith("http"))u="http://"+u;String host=u.substring(u.indexOf("://")+3);urls.put(host,u);}ring=new ConsistentHashingUtil(urls.keySet());this.secret=secret;this.factor=factor;}public String primary(String id){return ring.getNode(id);}public List<String> replicas(String primary){return urls.keySet().stream().filter(n->!n.equals(primary)).limit(Math.max(0,factor-1)).toList();}public void put(String n,String id,byte[] b){retry(()->{http.put().uri(url(n)+"/chunks/{id}",id).header("X-Storage-Secret",secret).header("X-Replication-Request","false").contentType(MediaType.APPLICATION_OCTET_STREAM).body(b).retrieve().toBodilessEntity();return null;});}public byte[] get(String n,String id){return retry(()->http.get().uri(url(n)+"/chunks/{id}",id).header("X-Storage-Secret",secret).retrieve().body(byte[].class));}public byte[] getWithFailover(String p,String[] replicas,String id){RuntimeException last=null;for(String n:concat(p,replicas)){try{return get(n,id);}catch(RuntimeException e){last=e;}}throw new IllegalStateException("No available replica for "+id,last);}public void delete(String n,String id){retry(()->{http.delete().uri(url(n)+"/chunks/{id}",id).header("X-Storage-Secret",secret).retrieve().toBodilessEntity();return null;});}private List<String> concat(String p,String[] r){var all=new ArrayList<String>();all.add(p);if(r!=null)all.addAll(Arrays.asList(r));return all;}private <T>T retry(java.util.concurrent.Callable<T> op){RuntimeException last=null;for(int i=0;i<3;i++){try{return op.call();}catch(Exception e){last=e instanceof RuntimeException r?r:new RuntimeException(e);try{Thread.sleep(100L*(1L<<i));}catch(InterruptedException x){Thread.currentThread().interrupt();throw last;}}}throw last;}private String url(String n){String u=urls.get(n);if(u==null)throw new IllegalArgumentException("Unknown storage node "+n);return u;}}
